const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),stage=document.querySelector('#stage'),overlay=document.querySelector('#overlay'),title=document.querySelector('#title'),description=document.querySelector('#description'),roomForm=document.querySelector('#room-form'),lobby=document.querySelector('#lobby'),meeting=document.querySelector('#meeting'),codeInput=document.querySelector('#code'),connection=document.querySelector('#connection'),roomLabel=document.querySelector('#room-label'),roomToggle=document.querySelector('#room-toggle'),shareCode=document.querySelector('#share-code'),playersLabel=document.querySelector('#players-label'),lobbyStatus=document.querySelector('#lobby-status'),roleEl=document.querySelector('#role'),identity=document.querySelector('#identity'),taskBar=document.querySelector('#task-bar'),notice=document.querySelector('#notice'),hint=document.querySelector('#hint'),voteOptions=document.querySelector('#vote-options'),voteStatus=document.querySelector('#vote-status'),meetingMessage=document.querySelector('#meeting-message'),meetingTimer=document.querySelector('#meeting-timer'),startRound=document.querySelector('#start-round'),taskButton=document.querySelector('#task'),killButton=document.querySelector('#kill'),reportButton=document.querySelector('#report'),emergencyButton=document.querySelector('#emergency');
const W=1400,H=900,VIEW_H=540,stations=[{id:0,x:205,y:180,name:'Navigation'},{id:1,x:705,y:170,name:'Reactor'},{id:2,x:1155,y:190,name:'Communications'},{id:3,x:230,y:700,name:'Storage'},{id:4,x:700,y:690,name:'Medbay'},{id:5,x:1170,y:705,name:'Electrical'}],keys=new Set(),pointers=new Map();let socket=null,playerId=null,state=null,roomName='',lastStatus='',codeVisible=true,noticeTimer=null,voteKey='',cameraX=0,cameraY=0,lastSend=0;
