function refreshCode(){shareCode.textContent=codeVisible?roomName:'••••••';roomToggle.textContent=codeVisible?'Hide':'Show';roomToggle.setAttribute('aria-label',codeVisible?'Hide room code':'Show room code');if(state)roomLabel.textContent=codeVisible?`ROOM ${roomName} · ${state.players.length}/10`:`ROOM HIDDEN · ${state.players.length}/10`}
