function renderVotes(){if(!state)return;const me=state.players.find(p=>p.id===playerId),living=state.players.filter(p=>p.alive&&!p.spectator);const key=JSON.stringify([state.voted,me?.alive,living.map(p=>p.id)]);voteStatus.textContent=me?.alive?(state.voted?'Vote submitted. Waiting for others.':`${state.votesCast} / ${living.length} votes received. Choose someone or skip.`):'You can watch the meeting.';if(key===voteKey)return;voteKey=key;voteOptions.replaceChildren();for(const target of [...living,{id:'skip',slot:null,color:null}]){const button=document.createElement('button');button.type='button';button.textContent=target.id==='skip'?'Skip vote':`● Crewmate ${target.slot}`;if(target.color)button.style.color=target.color;button.disabled=state.voted||!me?.alive;button.addEventListener('click',()=>{send({type:'vote',target:target.id});for(const b of voteOptions.querySelectorAll('button'))b.disabled=true;voteStatus.textContent='Vote submitted. Waiting for others.'});voteOptions.append(button)}}
